function reportsView(){if(!admin)return '';let rs=records.filter(r=>r.month===month&&r.name.toLowerCase().includes(query.toLowerCase())&&(filter==='Todas'||r.type===filter));let unique=list=>[...new Map(list.filter(r=>r.result==='Realizada').map(r=>[r.type+':'+r.person,r])).values()],completed=unique(rs),failed=rs.filter(r=>r.result!=='Realizada');return title('Relatórios','Resumo do período por tipo de atendimento e por responsável.',btn('Imprimir relatório','print'))+filters('<label>Tipo<select id="typefilter">'+options(['Todas','Visita','Ceia','Avulsa'].map(t=>[t,t]),filter)+'</select></label>')+stats([[completed.filter(r=>r.type==='Visita').length,'Visitas realizadas'],[completed.filter(r=>r.type==='Ceia').length,'Ceias entregues'],[completed.filter(r=>r.type==='Avulsa').length,'Avulsas realizadas'],[failed.length,'Tentativas sem atendimento']])+'<h3>Resultados por responsável</h3>'+table(['Responsável','Visitas realizadas','Ceias entregues','Avulsas realizadas','Tentativas sem atendimento'],workers.filter(w=>w.active||rs.some(r=>r.worker===w.id)).map(w=>{let list=unique(rs.filter(r=>r.worker===w.id));return '<tr><td>'+esc(w.name)+'</td><td>'+list.filter(r=>r.type==='Visita').length+'</td><td>'+list.filter(r=>r.type==='Ceia').length+'</td><td>'+list.filter(r=>r.type==='Avulsa').length+'</td><td>'+failed.filter(r=>r.worker===w.id).length+'</td></tr>'}))+'<p class="route-disclaimer">Indicadores baseados nos registros do período selecionado. Os detalhes e as observações ficam exclusivamente no Histórico.</p>'}

const subs=['Irmãos/Irmãs','Obreiros','Pastas de Visitas','Pastas de Ceias','Escalas e Rodízio','Autorizações','Relatórios'];
function adminView(){let html=title('Administração','Cadastros e organização do cuidado domiciliar.')+`<div class="subtabs">${subs.map(s=>`<button type="button" data-sub="${s}" class="${s===sub?'active':''}" ${s===sub?'aria-current="page"':''}>${s}</button>`).join('')}</div>`;if(sub==='Relatórios')return html+reportsView();if(sub==='Escalas e Rodízio')return html+scaleView();if(sub==='Autorizações')return html+grantView();if(sub.startsWith('Pastas'))return html+manageFolders(sub==='Pastas de Ceias');if(sub==='Obreiros')return html+title('Obreiros','Função ministerial e permissões são independentes.',btn('+ Cadastrar obreiro','workernew',true))+table(['Nome','Cargo','Ações'],workers.map(w=>`<tr><td>${esc(w.name)}${!w.active?'<small>Inativo</small>':''}</td><td>${w.role}</td><td>${btn('Editar','workeredit:'+w.id)}</td></tr>`));return html+title('Irmãos/Irmãs','Cadastro compartilhado; pastas de visitas e ceias independentes.',btn('+ Cadastrar irmão/irmã','personnew',true))+filters(`<label>Periodicidade<select id="periodfilter">${options(['Todas','Mensal','Semestral'].map(t=>[t,t]),filter)}</select></label><label>Pasta de visitas<select id="personFolderFilter">${options([['all','Todas as pastas'],['none','Sem pasta'],...folders.map(f=>[String(f.id),f.name])],personFolderFilter)}</select></label><label>Ceia em casa<select id="personCommunionFilter">${options([['all','Todos'],['yes','Sim'],['no','Não']],personCommunionFilter)}</select></label>`)+table(['Pessoa','Pasta de visitas','Periodicidade','Ceia em casa','Ações'],people.filter(p=>p.name.toLowerCase().includes(query.toLowerCase())&&(filter==='Todas'||p.period===filter)&&(personFolderFilter==='all'||(personFolderFilter==='none'?!p.folder:String(p.folder)===personFolderFilter))&&(personCommunionFilter==='all'||p.communion===(personCommunionFilter==='yes'))).map(p=>`<tr><td>${avatar(p)}${esc(p.name)}<small>${esc(addr(p))}${p.deathDate?' · Falecido(a)':!p.active?' · Inativa':''}</small></td><td>${esc(folders.find(f=>f.id===p.folder)?.name||'Sem pasta')}</td><td>${p.period}</td><td>${p.communion?badge('Sim','ok'):'Não'}</td><td>${btn('Ficha','view:'+p.id)}${btn('Editar','personedit:'+p.id)}</td></tr>`))}
function manageFolders(ceia){let fs=ceia?cfolders:folders;return title(sub,ceia?'Composição e responsáveis definidos manualmente.':'Irmãos/Irmãs mensais e semestrais na mesma pasta.',btn('+ Nova pasta','foldernew:'+(ceia?'Ceia':'Visita'),true))+table(['Pasta','Irmãos/Irmãs','Ações'],fs.map(f=>`<tr><td>${esc(f.name)}</td><td>${ceia?f.members.length:people.filter(p=>p.folder===f.id&&p.active).length}</td><td>${btn('Editar composição',`folderedit:${ceia?'Ceia':'Visita'}:${f.id}`)}</td></tr>`))}
function scaleView(){let a=assignments[month]||{},ca=cassign[month]||{};return filters()+`<div class="notice">Simule uma proposta e ajuste antes de publicar. O rodízio considera as atribuições já publicadas. Se sobrarem pastas, escolha os responsáveis manualmente; se sobrarem obreiros, eles ficam sem pasta no mês. Ceias não entram no rodízio.</div>`+btn('Simular rodízio mensal','simulate',true)+`<h3>${draft?'Proposta em rascunho':'Escala de visitas publicada / atual'}</h3>`+table(['Pasta de visitas','Responsável'],folders.map(f=>`<tr><td>${esc(f.name)}</td><td><select aria-label="Responsável por ${esc(f.name)}" data-assign="${f.id}">${options([['','Escolher responsável'],...workers.filter(w=>w.active&&w.rotation).map(w=>[w.id,w.name])],(draft||a)[f.id]||'')}</select></td></tr>`))+btn('Publicar escala de visitas','publish',true,!draft)+`<h3>Atribuição manual de ceias</h3>`+table(['Pasta de ceias','Responsável habilitado'],cfolders.map(f=>`<tr><td>${esc(f.name)}</td><td><select aria-label="Responsável por ${esc(f.name)}" data-cassign="${f.id}">${options([['','Escolher responsável'],...workers.filter(w=>w.active&&w.communion).map(w=>[w.id,w.name])],ca[f.id]||'')}</select></td></tr>`))+btn('Publicar atribuições de ceias','publishceia',true)}
function grantView(){return title('Autorizações individuais','Liberação extraordinária válida somente para pessoa, obreiro e mês escolhidos.',btn('+ Autorizar visita','grantnew',true))+filters()+table(['Pessoa','Obreiro autorizado','Validade','Ações'],grants.filter(g=>g.month===month).map((g)=>`<tr><td>${esc(person(g.person)?.name)}</td><td>${esc(who(g.worker))}</td><td>${g.month}</td><td>${btn('Revogar','revoke:'+g.id)}</td></tr>`))}
function noticeView(){return title('Notificações simuladas','Nenhuma mensagem é enviada para fora deste protótipo.',btn('Marcar todas como lidas','readall'))+table(['Aviso','Estado','Ação'],notices.map((n,i)=>({...n,index:i})).filter(n=>admin||n.worker===worker).map(n=>`<tr><td>${esc(n.text)}<small>Para: ${esc(who(n.worker))}</small></td><td>${n.read?'Lida':badge('Não lida')}</td><td>${btn('Abrir atribuição','notice:'+n.index)}</td></tr>`))}
function modal(t,body,save){$('#modal').innerHTML=`<div class="modalhead"><h2 id="modalTitle">${t}</h2>${btn('✕','close')}</div><form id="form">${body}<div class="modalfoot">${btn('Cancelar','close')}${save?'<button type="submit" class="primary">'+save+'</button>':''}</div></form>`;$('#modal').showModal()}
const field=(label,name,value='',type='text',required=false)=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`, selectField=(label,name,items,value)=>`<label>${label}<select name="${name}">${options(items,value)}</select></label>`, check=(label,name,value)=>`<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;
function personForm(id){let p=person(id)||{active:true,period:'Mensal'};modal(id?'Editar irmão/irmã':'Cadastrar irmão/irmã',`<div class="formgrid">${field('Nome completo *','name',p.name,'text',true)}${field('Telefone fictício','phone',p.phone)}${field('Data de nascimento','birthDate',p.birthDate,'date')}${field('Data de falecimento','deathDate',p.deathDate,'date')}<p class="wide muted">Informar o falecimento desativa a ficha e retira atendimentos pendentes dos itinerários. Os registros anteriores são preservados.</p>${field('Logradouro *','street',p.street,'text',true)}${field('Número *','number',p.number,'text',true)}${field('Bairro *','area',p.area,'text',true)}${field('Cidade *','city',p.city,'text',true)}${field('Estado','state',p.state)}${field('Complemento / referência','reference',p.reference)}${selectField('Periodicidade','period',[['Mensal','Mensal'],['Semestral','Semestral — maio e outubro']],p.period)}${selectField('Pasta de visitas','folder',[['','Sem pasta'],...folders.map(f=>[f.id,f.name])],p.folder)}${check('Recebe ceia em casa','communion',p.communion)}${check('Cadastro ativo','active',p.active)}<label>Foto de perfil (opcional)<input type="file" name="photo" accept="image/*"></label><label>Foto da fachada (opcional)<input type="file" name="facade" accept="image/*"></label><div class="wide muted">As fotos ficam apenas nesta sessão. Use imagens fictícias. Sem consulta de endereço.</div></div>`,'Salvar cadastro');$('#form').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),data=Object.fromEntries([...f].filter(([k,v])=>!(v instanceof File)));data.folder=+f.get('folder')||null;let error=validateLifeDates(data);if(error)return toast(error);data.active=f.has('active')&&!data.deathDate;data.communion=f.has('communion');for(let k of ['photo','facade']){let file=f.get(k);if(file?.size){if(!file.type.startsWith('image/'))return toast('Selecione uma imagem.');if(file.size>5000000)return toast('Use uma imagem de até 5 MB.');data[k]=await new Promise(resolve=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(file)})}}if(id)Object.assign(p,data);else people.push({...data,id:Math.max(...people.map(p=>p.id))+1,distance:2.4});if(data.deathDate)removeDeceasedPending(id||people[people.length-1].id);savePlanState();if(!data.communion)cfolders.forEach(f=>f.members=f.members.filter(x=>x!==id));close();toast('Cadastro salvo nesta sessão.')};}
function workerForm(id){let w=workers.find(w=>w.id===id)||{active:true,rotation:true,adHoc:true};modal(id?'Editar obreiro':'Cadastrar obreiro',`<div class="formgrid">${field('Nome completo *','name',w.name,'text',true)}${selectField('Função ministerial','role',['Obreiro','Diácono','Evangelista','Cooperador'].map(t=>[t,t]),w.role)}${['active','rotation','communion','adHoc','admin'].map((k,i)=>check(['Ativo','Participa do rodízio','Habilitado para ceias','Autorizado para avulsas','Administrador do módulo'][i],k,w[k])).join('')}</div>`,'Salvar obreiro');$('#form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),data={name:f.get('name'),role:f.get('role')};['active','rotation','communion','adHoc','admin'].forEach(k=>data[k]=f.has(k));if(id)Object.assign(w,data);else workers.push({...data,id:Math.max(...workers.map(w=>w.id))+1});close();toast('Obreiro e permissões atualizados.')};}
function folderForm(type,id){let fs=type==='Ceia'?cfolders:folders,f=fs.find(f=>f.id===id)||{};modal(id?'Editar pasta':'Nova pasta',`<div class="formgrid">${field('Nome da pasta *','name',f.name,'text',true)}<div class="wide checklist">${people.filter(p=>p.active&&(type!=='Ceia'||p.communion)).map(p=>check(p.name,'member'+p.id,type==='Ceia'?f.members?.includes(p.id):p.folder===id)).join('')}</div><div class="wide muted">Selecionar uma pessoa transfere seu vínculo para esta pasta. As pastas de visitas e ceias são independentes.</div></div>`,'Salvar pasta');$('#form').onsubmit=e=>{e.preventDefault();let fd=new FormData(e.target);if(!id){f={id:Math.max(0,...fs.map(f=>f.id))+1};fs.push(f)}f.name=fd.get('name');let members=people.filter(p=>fd.has('member'+p.id)).map(p=>p.id);if(type==='Ceia'){cfolders.forEach(other=>{other.members=(other.members||[]).filter(pid=>!members.includes(pid))});f.members=members}else people.forEach(p=>{if(members.includes(p.id))p.folder=f.id;else if(p.folder===f.id)p.folder=null});close();toast('Pasta atualizada.')};}
function avForm(){modal('Nova visita avulsa',`<div class="formgrid">${selectField('Usar pessoa cadastrada (opcional)','existing',[['','Cadastro simplificado'],...people.filter(p=>p.active).map(p=>[p.id,p.name])],'')}${field('Nome completo *','name','','text',true)}${field('Endereço fictício *','address','','text',true)}${field('Período *','month',month,'month',true)}${selectField('Responsável autorizado','worker',workers.filter(w=>w.active&&w.adHoc).map(w=>[w.id,w.name]),worker)}<label>Orientações<textarea name="notes"></textarea></label></div>`,'Atribuir visita');$('[name=existing]').onchange=e=>{let p=person(e.target.value);if(p){$('[name=name]').value=p.name;$('[name=address]').value=addr(p)}};$('#form').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(!f.worker)return toast('Cadastre um obreiro autorizado.');f.id=Math.max(0,...adhoc.map(p=>p.id))+1;f.worker=+f.worker;f.distance=2.1;adhoc.push(f);notify('Nova visita avulsa: '+f.name,'avulsas',f.worker);close();toast('Visita avulsa atribuída. Aviso simulado criado.')};}
function grantForm(){modal('Autorizar visita extraordinária',`<div class="formgrid">${selectField('Pessoa semestral','person',people.filter(p=>p.active&&p.period==='Semestral').map(p=>[p.id,p.name]))}${selectField('Somente este obreiro','worker',workers.filter(w=>w.active).map(w=>[w.id,w.name]),worker)}${field('Mês de validade *','month',month,'month',true)}${field('Justificativa *','reason','','text',true)}</div>`,'Autorizar');$('#form').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));grants.push({...f,id:Date.now(),person:+f.person,worker:+f.worker});notify('Visita extraordinária autorizada para '+person(f.person).name,'pastas',+f.worker);close();toast('Autorização individual criada para '+f.month)};}
function viewPerson(id){let p=person(id);if(!p)return;modal('Ficha do irmão/irmã',`<div class="formgrid"><div class="person-identity">${avatar(p)}<h3>${esc(p.name)}</h3><p>${esc(p.phone)}</p></div><div><h3>Endereço fictício</h3><p>${esc(addr(p))}</p><p>${esc(p.reference)}</p></div><div>${badge(p.period)} <p>Recebe ceia: ${p.communion?'Sim':'Não'}</p></div><div>${p.facade?`<img src="${esc(p.facade)}" style="max-width:100%;max-height:200px" alt="Fachada fictícia">`:'Sem foto de fachada'}</div></div>`);if(admin)$('#modalTitle').insertAdjacentHTML('afterend','<button type="button" class="ficha-edit" data-op="editFicha:'+p.id+'" aria-label="Editar ficha de '+esc(p.name)+'" title="Editar ficha"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 4 5 5M4 20l4-1L21 6l-4-4L4 15Z"/></svg></button>')}
function recordForm(type,id){let p=type==='Avulsa'?adhoc.find(p=>p.id===id):type==='Ceia'?routeSource.find(p=>p.id===id)||person(id):person(id);if(!p||!allowed(type,p)||(type==='Visita'&&!eligible(p))||done(type,id))return toast('Atendimento indisponível para este perfil e período.');modal(type==='Ceia'?'Registrar ceia':'Visitei / Não visitei',`<div class="notice">${esc(p.name)} · ${mlabel()}<br>Responsável do registro: ${esc(who(worker))}</div><div class="formgrid">${selectField('Resultado','result',[['Realizada',type==='Ceia'?'Ceia entregue':'Visita realizada'],['Não realizada',type==='Ceia'?'Ceia não entregue':'Visita não realizada']],'Realizada')}${selectField('Motivo se não realizada','reason',[['','Selecione'],['Pessoa ausente','Pessoa ausente'],['Não foi possível atender','Não foi possível atender'],['Mudança de endereço','Mudança de endereço'],['Outro','Outro']],'')}<label class="wide">Observações opcionais<textarea name="notes" rows="3"></textarea></label><label class="wide">Erros no cadastro (opcional)<textarea name="registrationErrors" rows="3" placeholder="Ex.: endereço incorreto, telefone desatualizado ou nome a corrigir"></textarea><small>Informe aqui somente correções necessárias no cadastro. O administrador poderá consultar esta indicação no histórico.</small></label></div>`,'Confirmar registro');$('#form').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(f.result!=='Realizada'&&!f.reason)return toast('Selecione o motivo da não realização.');records.push({...f,type,person:id,name:p.name,month,worker,date:new Date().toLocaleString('pt-BR'),folder:type==='Avulsa'?'Avulsa':(type==='Ceia'?cfolders.find(f=>f.id===p.cf):folders.find(f=>f.id===p.folder))?.name||''});selected.delete(id);savePlanState();close();toast('Registro salvo. O itinerário continua ativo.')};}
function routeModal(type){openPlan(type,itineraryCandidates(type))}
function communionHome(){if(!admin&&!wm().communion)return '<p class="notice">Este usuário não está habilitado para levar ceia.</p>';return itineraryHome('Ceia')}
function routeContent(){let groups=groupItinerary(route,routeType);return '<p class="muted">'+groups.length+' paradas · '+route.length+' atendimentos individuais · '+(routeType==='Ceia'?'Ceias domiciliares':routeType==='Avulsa'?'Visitas avulsas':'Visitas domiciliares')+'</p>'+routeOriginControls()+'<div class="route-order">'+btn('Mais próximas','sortnear')+btn('Mais distantes','sortfar')+'</div><div class="itinerary-stops">'+groups.map((g,i)=>residenceStop(g,i,groups.length)).join('')+'</div><p class="route-disclaimer">Uma navegação por residência vinculada, com registros individuais. Distâncias demonstrativas. A ordem permanece até finalizar ou recomeçar.</p><div class="plan-lifecycle"><button type="button" class="primary" data-op="finish:'+routeType+'">Finalizar itinerário</button><button type="button" data-op="restart:'+routeType+'">Recomeçar itinerário</button></div>'}
function showRoute(){let plan=currentPlan(routeType);if(plan){plan.stops=route.map(p=>({...p}));savePlanState()}if(['Visita','Ceia'].includes(routeType)){tab=routeType==='Ceia'?'ceias':'visitar';folderOpen=null;render();return}modal('Meu itinerário',routeContent());$('#modal').classList.add('route-dialog')}
function routePhotos(p){let live=routeType==='Avulsa'?adhoc.find(a=>a.id===p.id):person(p.id);p=live||p;return '<div class="route-photos">'+(p.photo?'<figure><img class="avatar" src="'+esc(p.photo)+'" alt="Foto fictícia de '+esc(p.name)+'"><figcaption>Foto</figcaption></figure>':'')+(p.facade?'<figure><img class="route-facade avatar" src="'+esc(p.facade)+'" alt="Fachada fictícia da residência de '+esc(p.name)+'"><figcaption>Fachada</figcaption></figure>':'')+'</div>'}
function routeOriginControls(){let origin=currentPlan(routeType)?.origin;return '<section class="route-origin"><h3>Ponto de partida</h3><div class="origin-actions"><button type="button" data-op="originCurrent">Minha localização (simulada)</button></div><label>Ou informe uma localização desejada<input id="routeOrigin" type="text" placeholder="Endereço ou ponto de referência" value="'+esc(origin?.mode==='manual'?origin.label:'')+'"></label><button type="button" data-op="originSave">Usar este ponto de partida</button><p class="muted">'+(origin?'Partida: '+esc(origin.label):'Escolha o ponto de partida.')+' · Demonstração sem GPS ou cálculo de distância real. Alterar a partida preserva a ordem das paradas.</p></section>'}
document.addEventListener('click',e=>{let b=e.target.closest('[data-op]');if(!b)return;let action=b.dataset.op;if(!['originCurrent','originSave'].includes(action))return;let plan=currentPlan(routeType);if(!plan)return;let label=action==='originCurrent'?'Minha localização simulada':$('#routeOrigin').value.trim();if(!label)return toast('Informe um endereço ou ponto de referência.');plan.origin={mode:action==='originCurrent'?'simulated':'manual',label};savePlanState();if($('#modal').open)$('#modal').close();showRoute()});
function close(){if($('#modal').open)$('#modal').close();render()}
function simulate(){let ws=workers.filter(w=>w.active&&w.rotation);if(!ws.length)return toast('Nenhum obreiro ativo no rodízio.');let history=Object.entries(assignments).filter(([m])=>m<month),counts=w=>history.reduce((n,[,a])=>n+Object.values(a).filter(id=>id===w.id).length,0),rank=ws.slice().sort((a,b)=>counts(a)-counts(b)||a.id-b.id),used=new Set();draft={};folders.forEach(f=>{let candidates=rank.filter(w=>!used.has(w.id));candidates.sort((a,b)=>{let seen=w=>history.filter(([,a])=>a[f.id]===w.id).length;return seen(a)-seen(b)||counts(a)-counts(b)||a.id-b.id});let w=candidates[0];draft[f.id]=w?.id||'';if(w)used.add(w.id)});render();toast('Proposta gerada. Revise e publique para confirmar.')}
document.addEventListener('click',e=>{let s=e.target.closest('[data-sub]');if(s){sub=s.dataset.sub;query='';filter='Todas';render();return}let b=e.target.closest('[data-action]');if(!b)return;let [a,x,y]=b.dataset.action.split(':');if((a.startsWith('person')||a.startsWith('worker')||a.startsWith('folder')||['simulate','publish','publishceia','grantnew','revoke','newav'].includes(a))&&!admin)return;switch(a){case'tab':tab=x;folderOpen=null;selected.clear();query='';filter='Todas';render();break;case'clear':query='';filter='Todas';personFolderFilter='all';personCommunionFilter='all';render();break;case'open':folderOpen=+x;selected.clear();render();break;case'back':folderOpen=null;selected.clear();render();break;case'close':close();break;case'personnew':personForm();break;case'personedit':personForm(+x);break;case'workernew':workerForm();break;case'workeredit':workerForm(+x);break;case'foldernew':folderForm(x);break;case'folderedit':folderForm(x,+y);break;case'view':viewPerson(+x);break;case'newav':avForm();break;case'grantnew':grantForm();break;case'revoke':grants=grants.filter(g=>g.id!==+x);render();break;case'record':recordForm(x,+y);break;case'route':routeModal(x);break;case'sortnear':sortResidenceRoute(false);$('#modal').close();showRoute();break;case'sortfar':sortResidenceRoute(true);$('#modal').close();showRoute();break;case'up':case'down':{moveResidenceRoute(+x,a==='up'?-1:1);$('#modal').close();showRoute();break}case'simulate':simulate();break;case'publish':if(Object.values(draft||{}).filter(Boolean).length!==folders.length)return toast('Escolha um responsável para cada pasta excedente.');assignments[month]={...draft};Object.entries(draft).forEach(([id,w])=>notify(`${folders.find(f=>f.id===+id).name} atribuída em ${mlabel()}`,'pastas',w));draft=null;render();toast('Escala publicada e avisos simulados criados.');break;case'publishceia':if(cfolders.some(f=>!cassign[month]?.[f.id]))return toast('Escolha um responsável para cada pasta de ceias.');Object.entries(cassign[month]).forEach(([id,w])=>notify(`${cfolders.find(f=>f.id===+id).name} atribuída em ${mlabel()}`,'ceias',w));render();toast('Atribuições de ceias publicadas.');break;case'notice':{let n=notices[+x];n.read=true;tab=n.tab;folderOpen=null;render();break}case'readall':notices.forEach(n=>{if(admin||n.worker===worker)n.read=true});render();break;case'print':window.print();break}});
