function folderLocationSummary(f,ps){let areas=[...new Set(ps.map(p=>String(p.area||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));return `<div class="folder-location"><p><span>Região de referência</span><strong>${esc(f.region||'Não definida')}</strong></p><p><span>Bairros desta pasta</span>${esc(areas.join(' · ')||'Nenhum bairro cadastrado')}</p></div>`}

function validateLifeDates(data){let now=new Date(),today=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');for(const key of ['birthDate','deathDate']){const value=data[key];if(value&&(!/^\d{4}-\d{2}-\d{2}$/.test(value)||Number.isNaN(new Date(value+'T12:00:00').getTime())||new Date(value+'T12:00:00').toISOString().slice(0,10)!==value))return 'Informe uma data válida.';if(value&&value>today)return 'Nascimento e falecimento não podem estar no futuro.'}if(data.birthDate&&data.deathDate&&data.deathDate<data.birthDate)return 'O falecimento não pode ser anterior ao nascimento.';return ''}
