document.addEventListener('click',e=>{let button=e.target.closest('[data-sort-column]');if(!button)return;let table=button.closest('table'),th=button.closest('th'),index=+button.dataset.sortColumn,descending=th.getAttribute('aria-sort')==='ascending';let value=cell=>{let text=cell?.textContent.trim()||'';if(/^\d{2}\/\d{2}\/\d{4}$/.test(text))return text.split('/').reverse().join('-');return text};let rows=Array.from(table.tBodies[0].rows);if(rows.some(r=>r.cells.length!==table.tHead.rows[0].cells.length))return;rows.sort((a,b)=>value(a.cells[index]).localeCompare(value(b.cells[index]),'pt-BR',{numeric:true,sensitivity:'base'})*(descending?-1:1));for(const row of rows)table.tBodies[0].appendChild(row);for(const header of table.querySelectorAll('th[aria-sort]')){header.setAttribute('aria-sort','none');header.querySelector('span').textContent='↕'}th.setAttribute('aria-sort',descending?'descending':'ascending');button.querySelector('span').textContent=descending?'↓':'↑'});

