document.addEventListener('click',e=>{let b=e.target.closest('[data-op]');if(!b)return;let [action,type,id]=b.dataset.op.split(':');if(action==='routeFicha'){if($('#modal').open)$('#modal').close();viewRoutePerson(type,+id)}if(action==='editFicha'&&admin&&person(type)){if($('#modal').open)$('#modal').close();personForm(+type)}});

function liveRoutePerson(p,type=routeType){return {...p,...(type==='Avulsa'?adhoc.find(a=>a.id===p.id):person(p.id))}}
function residenceKey(p,type=routeType){let live=liveRoutePerson(p,type);return type!=='Avulsa'&&live.householdId?'house:'+live.householdId:type+':'+p.id}
function groupItinerary(stops,type=routeType){let groups=new Map();for(const p of stops){let key=residenceKey(p,type);if(!groups.has(key))groups.set(key,{key,members:[],type});groups.get(key).members.push(p)}return [...groups.values()]}
function routeRecord(type,id){return records.slice().reverse().find(r=>r.type===type&&r.person===id&&r.month===month)}
function canServeRoute(p,type=routeType){let live=liveRoutePerson(p,type);return allowed(type,live)&&(type==='Avulsa'||live.active)&&(type!=='Visita'||eligible(live))&&(type!=='Ceia'||live.communion)&&!done(type,p.id)}
function residenceStatus(g){let results=g.members.map(p=>done(g.type,p.id)?{result:'Realizada'}:routeRecord(g.type,p.id));let filled=results.filter(Boolean).length,failed=results.some(r=>r&&r.result!=='Realizada');return {complete:filled===g.members.length,failed,filled,label:filled===g.members.length?(failed?'Registros concluídos · retorno possível':'Atendimentos concluídos'):filled+' de '+g.members.length+' resultados registrados'}}
function relatedResidenceMembers(g){if(g.type==='Avulsa'||!g.key.startsWith('house:'))return [];let p=liveRoutePerson(g.members[0],g.type);return people.filter(other=>other.active&&other.householdId===p.householdId&&!g.members.some(m=>m.id===other.id)).map(other=>({...other,...(g.type==='Ceia'?{cf:cfolders.find(f=>f.members.includes(other.id))?.id}:{} )})).filter(other=>allowed(g.type,other)&&(g.type!=='Ceia'||other.communion))}
function residenceMember(p,included=true){let live=liveRoutePerson(p),result=routeRecord(routeType,p.id),can=canServeRoute(p),status=!included?(can?'Fora deste itinerário':routeType==='Visita'&&!eligible(live)?'Indisponível neste mês':'Indisponível para atendimento'):done(routeType,p.id)?'Realizada':result?'Não realizada · retorno possível':can?'Pendente':'Indisponível neste mês';return '<article class="residence-member"><div class="visit-person">'+avatar(live)+'<h4>'+esc(live.name)+'</h4></div>'+routeContact(live)+'<p class="secondary-meta">'+esc(status)+(routeType==='Visita'?' · '+esc(live.period):'')+'</p>'+(included?'<div class="visit-actions"><button type="button" data-op="register:'+routeType+':'+p.id+'" '+(!can?'disabled':'')+'>'+actionIcon('check')+(routeType==='Ceia'?'Registrar ceia':'Visitei / Não visitei')+'</button></div>':'')+(included||can?itineraryAction(live,routeType):'<p class="muted">Somente com disponibilidade ou autorização individual.</p>')+'</article>'}
function residenceStop(g,index,total){let first=liveRoutePerson(g.members[0]),title=g.key.startsWith('house:')?'Residência de '+g.members.map(p=>liveRoutePerson(p).name.split(' ')[0]).join(' e '):first.name,available=g.members.find(p=>canServeRoute(p)),state=residenceStatus(g),related=relatedResidenceMembers(g);return '<section class="itinerary-stop residence-stop"><div class="stop-heading"><span class="stop-number">'+(index+1)+'</span><h3>'+esc(title)+'</h3><div class="reorder"><button type="button" data-action="up:'+index+'" aria-label="Mover '+esc(title)+' para cima" '+(!index?'disabled':'')+'>↑</button><button type="button" data-action="down:'+index+'" aria-label="Mover '+esc(title)+' para baixo" '+(index===total-1?'disabled':'')+'>↓</button></div></div>'+(first.facade?'<figure class="residence-facade"><img class="avatar" src="'+esc(first.facade)+'" alt="Fachada fictícia de '+esc(title)+'"><figcaption>Fachada · toque para ampliar</figcaption></figure>':'')+'<p class="visit-address">'+esc(first.address||addr(first))+'</p><div class="visit-actions"><button type="button" class="primary" data-op="navigateResidence:'+index+'" '+(!available?'disabled':'')+'>'+actionIcon('navigate')+'Navegar até o endereço</button></div><p class="residence-progress" role="status">'+esc(state.label)+'</p><div class="residence-members">'+g.members.map(p=>residenceMember(p)).join('')+'</div>'+(related.length?'<details class="residence-related"><summary>Outros moradores vinculados ('+related.length+')</summary>'+related.map(p=>residenceMember(p,false)).join('')+'</details>':'')+'<p class="secondary-meta">'+esc(first.distance)+' km fictícios · '+g.members.length+' atendimento(s) neste percurso</p><button type="button" class="itinerary-remove" data-op="removeResidence:'+g.members[0].id+'">Remover residência do itinerário</button></section>'}
function moveResidenceRoute(index,delta){let groups=groupItinerary(route),other=index+delta;if(other<0||other>=groups.length)return;[groups[index],groups[other]]=[groups[other],groups[index]];route=groups.flatMap(g=>g.members)}
function sortResidenceRoute(descending){let groups=groupItinerary(route);groups.sort((a,b)=>(Number(liveRoutePerson(a.members[0]).distance||0)-Number(liveRoutePerson(b.members[0]).distance||0))*(descending?-1:1));route=groups.flatMap(g=>g.members)}
function itineraryHome(type){routeType=type;let plan=currentPlan(type);let titleText=type==='Ceia'?'Meu itinerário de ceias':'Meu itinerário';if(!plan)return '<section class="operator-home">'+title(titleText,esc(who(worker))+' · '+mlabel())+'<details class="itinerary-period"><summary>Alterar período</summary>'+filters()+'</details><p>Nenhum itinerário ativo. Habilite quando quiser iniciar o percurso. Os cards continuam em Minhas Pastas.</p><button class="primary" data-op="buildRoute:'+type+'">Habilitar itinerário</button><button data-op="folderKind:'+type+'">Minhas Pastas</button></section>';route=plan.stops.map(p=>({...p}));routeSource=route;return '<section class="operator-home itinerary-home">'+title(titleText,esc(who(worker))+' · '+mlabel(),'<button class="text-button" data-op="folderKind:'+type+'">Ver cards em Minhas Pastas</button>')+'<details class="itinerary-period"><summary>Alterar período</summary>'+filters()+'</details>'+routeContent()+'</section>'}
