document.addEventListener('click',e=>{let button=e.target.closest('[data-op]');if(!button)return;let [action,arg]=button.dataset.op.split(':');if(action==='navigateResidence'){let group=groupItinerary(route)[+arg],target=group?.members.find(p=>canServeRoute(p));if(target)navigateResidencePreview(group)}if(action==='removeResidence'){let plan=currentPlan(routeType);if(!plan)return;let p=plan.stops.find(p=>p.id===+arg);if(!p)return;let key=residenceKey(p);plan.stops=plan.stops.filter(other=>residenceKey(other)!==key);route=plan.stops.map(p=>({...p}));savePlanState();if($('#modal').open)$('#modal').close();showRoute();toast('Residência removida apenas do itinerário. Registros preservados.')}if(action==='buildRoute'){if(arg==='Ceia'&&!admin&&!wm().communion)return;openPlan(arg,itineraryCandidates(arg))}if(action==='folderKind'){if(arg==='Ceia'&&!admin&&!wm().communion)return;tab=arg==='Ceia'?'pastasceias':'pastas';folderOpen=null;query='';selected.clear();render()}});

