function keepActiveAdminTab(restoreFocus=false){if(tab!=='admin')return;let button=$('.subtabs button.active'),strip=button?.parentElement;if(!strip)return;if(restoreFocus)button.focus({preventScroll:true});let max=Math.max(0,strip.scrollWidth-strip.clientWidth),left=Math.max(0,Math.min(max,button.getBoundingClientRect().left-strip.getBoundingClientRect().left+strip.scrollLeft-(strip.clientWidth-button.offsetWidth)/2));if(typeof strip.scrollTo==='function')strip.scrollTo({left,top:0,behavior:'auto'});else strip.scrollLeft=left}
